("medtronic","Medtronic","https://www.medtronic.com/","Medtronic is one of the world's largest medical device companies.","Medtronic uses a strong navy wordmark with no symbol.","Tight spacing and heavy letters make the name feel solid and technical.",[("wordmark only",0.15,0.3),("navy",0.5,0.2),("heavy letters",0.8,0.85)]),
("stryker","Stryker","https://www.stryker.com/","Stryker is a US medical technology company known for orthopedic and surgical products.","A heavy, rounded black wordmark has the look of strong industrial equipment.","The low, wide letters feel stable and dependable.",[("heavy lowercase",0.2,0.3),("black",0.5,0.2),("low + wide",0.8,0.85)]),
